Body:[
	{id:1,V:["Instructions for Completing Audit Time Calculation"],A:[323,323,323,323,323,323,323,323,323,323,323,323,323,147,147],CS:{A:13}},
	{id:2},
	{id:3},
	{id:4,V:["Two (2) options are available to determine an audit duration. When using this form, Auditing Organizations are expected to use one tab, not both."]},
	{id:5},
	{id:6,V:["Tab: Audit Duration Calculation #1 "],A:[147]},
	{id:7,V:["This worksheet requires the user to specify the number of tasks to be completed for each process"]},
	{id:8,V:["If duplicate tasks are required, the task can be counted more than once."]},
	{id:9},
	{id:10,V:["Tab: Audit Duration Calculation #2"],A:[147]},
	{id:11,V:["This worksheet requires the user to specify each applicable task, by indicating: "]},
	{id:12,V:[,"<span style=\"font-weight:bold;\">0</span>"]},
	{id:13,V:[,"<span style=\"font-weight:bold;\">1</span>"]},
	{id:14,V:[,"The appropriate digit (2, 3, 4, …) if the audit requires the task to be accomplished more than once (e.g. increase the sampling rate)"]},
	{id:15},
	{id:16,V:["This worksheet is nine (9) pages long. It can also shown as a one page Synthetic View, hiding the details of the tasks."]},
	{id:17,V:["On the top right corner of the worksheet, two buttons allow to toggle from expanded to synthetic view."],A:[,147]},
	{id:18,A:[,147]}
],
